// Subcategory grouping for the catalog: prefer an explicit `subcategory`, else
// derive a sensible group (windows by style, beds by type) so big systems break
// into scannable groups ("all mattresses", "all sliders", "all base cabinets").
const WIN_STYLE = { "t-vent": "T-Vent windows", slider: "Sliders", awning: "Awning windows", fixed: "Fixed windows", bunk: "Bunk windows", "project-out": "Project-out windows" };
const subGroupOf = (c) => {
  if (c.subcategory) return c.subcategory;
  const t = c.tags || [];
  if (c.category === "Window") return (c.style && WIN_STYLE[c.style]) || "Windows";
  if (c.category === "Bed") {
    if (t.includes("lift")) return "Lift beds";
    if (t.includes("murphy")) return "Murphy beds";
    if (t.includes("bed-rail") || t.includes("slat") || t.includes("actuator")) return "Bed hardware";
    return "Bed platforms";
  }
  if (c.category === "Cooktop") {
    if (t.includes("diesel")) return "Diesel cooktops";
    if (t.includes("propane")) return "Propane cooktops";
    return "Induction cooktops";
  }
  if (c.category === "Refrigerator") {
    if (t.includes("drawer")) return "Drawer fridges";
    if (t.includes("portable")) return "Portable fridges";
    return "Built-in fridges";
  }
  if (c.category === "Bumper") return t.includes("rear") ? "Rear bumpers" : "Front bumpers";
  if (c.category === "Awning") {
    if (t.includes("bracket")) return "Awning brackets";
    if (t.includes("room")) return "Awning rooms";
    if (t.includes("portable")) return "Portable awnings";
    if (t.includes("270") || t.includes("180")) return "270\u00b0 / 180\u00b0 awnings";
    if (t.includes("batwing")) return "Batwing awnings";
    if (t.includes("roll-out")) return "Roll-out awnings";
    return "Cassette awnings";
  }
  if (c.category === "Seating") {
    if ((c.tags || []).includes("swivel") || /swivel/i.test(c.name || "")) return "Seat swivels";
    if ((c.tags || []).includes("dinette")) return "Dinettes";
    return "Benches & seating";
  }
  if (c.category === "Solar Panel") {
    if (t.includes("walkable")) return "Walkable flexible";
    if (t.includes("flexible")) return "Flexible panels";
    if (t.includes("portable")) return "Portable panels";
    return "Rigid panels";
  }
  if (c.category === "Base Cabinet") {
    const s = ((c.name||"")+" "+(c.model||"")).toLowerCase();
    if (/sink/.test(s)) return "Sink cabinets";
    if (/fridge|refriger/.test(s)) return "Fridge cabinets";
    if (/cooktop|stove/.test(s)) return "Cooktop cabinets";
    if (/pantry/.test(s)) return "Pull-out pantries";
    if (/bench/.test(s)) return "Bench cabinets";
    if (/drawer/.test(s)) return "Drawer cabinets";
    if (/galley|kitchen/.test(s)) return "Galley cabinets";
    return "Base cabinets";
  }
  if (c.category === "Galley") {
    const w = (c.dims && c.dims.w) || 0;
    if (w >= 60) return "Full galley (60\"+)";
    if (w >= 44) return "Large galley (44-60\")";
    if (w >= 30) return "Medium galley (30-44\")";
    return "Small galley (<30\")";
  }
  return c.category;
};

