const SHELL_DEFAULTS = { "Insulation": "mat-thinsulate", "Wall Panel": "mat-ply-wall", "Ceiling Panel": "mat-ply-ceiling", "Flooring": "mat-lvp", "Ltrack": "", "Framing": "wood" };
const FRAMING_FACTOR = { wood: { w: 1, c: 1 }, tslot: { w: 1.35, c: 1.8 } };
const NEEDS_FURRING = ["mat-ply-wall", "mat-frp", "mat-cedar-wall", "mat-ply-ceiling", "mat-cedar-ceiling", "mat-pvc-plank"];
const COVERAGE = {
  "mat-thinsulate": 15, "mat-polyiso-1": 32, "mat-xps-1": 32, "mat-sprayfoam": 180, "mat-wool": 40, "mat-denim": 40, "mat-reflectix": 100,
  "mat-butyl": 36, "mat-ccf": 40, "mat-vapor": 220,
  "mat-ply-wall": 32, "mat-cedar-wall": 14, "mat-frp": 32, "mat-pmf": 50,
  "mat-cedar-ceiling": 14, "mat-ply-ceiling": 32, "mat-pvc-plank": 10,
  "mat-subfloor": 32, "mat-lvp": 20, "mat-rubber": 100, "mat-minicell": 32,
};
function shellAreas(van) {
  const L = van.intLength || 0, W = van.intWidth || 0, H = van.roofH || 0;
  const wall = Math.round((2 * L * H * 0.62 + W * H * 0.45) / 144);
  const ceiling = Math.round((L * W) / 144);
  return { wall, ceiling, floor: ceiling, shell: wall + ceiling };
}
const MATERIALS_BY_CAT = (() => {
  const m = {};
  for (const c of DB) if (c.system === "material") (m[c.category] ||= []).push(c);
  return m;
})();
function isMaterialCid(cid) { const c = DB_BY_ID[cid]; return !!c && c.system === "material"; }
function buildShellPlaced(choices, van) {
  const areas = shellAreas(van); const out = [];
  for (const q of SHELL_QUESTIONS) {
    const cid = choices[q.category]; if (!cid) continue;
    const cov = COVERAGE[cid] || 32; const area = areas[q.surface] || areas.wall;
    const qty = Math.max(1, Math.ceil(area / cov));
    out.push({ iid: uid(), cid, qty, x: 0, y: 0, material: true });
  }
  // rigid wall/ceiling panels (e.g. 1/4" birch ply) need furring strips on the metal first
  let furArea = 0;
  if (NEEDS_FURRING.includes(choices["Wall Panel"])) furArea += areas.wall;
  if (NEEDS_FURRING.includes(choices["Ceiling Panel"])) furArea += areas.ceiling;
  if (furArea > 0) out.push({ iid: uid(), cid: "mat-furring", qty: Math.max(2, Math.ceil(furArea / 10)), x: 0, y: 0, material: true });
  // L-track (both walls), only if asked
  if (choices.Ltrack === "yes") out.push({ iid: uid(), cid: "mat-ltrack", qty: Math.max(2, Math.ceil((van.intLength * 2) / 48)), x: 0, y: 0, material: true });
  return out;
}
